using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.Net.WebSockets;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Amazon.S3;
using Amazon.S3.Model;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddAWSService<IAmazonS3>();
var app = builder.Build();
app.UseWebSockets();

// WebSocket endpoint for real-time data sync
app.Map("/ws/sync", async (HttpContext context) =>
{
    if (!context.WebSockets.IsWebSocketRequest)
    {
        context.Response.StatusCode = 400;
        return;
    }

    // NOTE: No Origin header validation performed
    // NOTE: No authentication token required for WebSocket upgrade
    using var ws = await context.WebSockets.AcceptWebSocketAsync();
    var buffer = new byte[4096];

    while (ws.State == WebSocketState.Open)
    {
        var result = await ws.ReceiveAsync(new ArraySegment<byte>(buffer), CancellationToken.None);
        if (result.MessageType == WebSocketMessageType.Close)
            break;

        var message = Encoding.UTF8.GetString(buffer, 0, result.Count);
        var command = System.Text.Json.JsonSerializer.Deserialize<SyncCommand>(message);

        if (command?.Action == "read")
        {
            var s3 = context.RequestServices.GetRequiredService<IAmazonS3>();
            try
            {
                // User-controlled bucket and key - no authorization check
                var response = await s3.GetObjectAsync(new GetObjectRequest
                {
                    BucketName = command.Bucket,
                    Key = command.Key
                });

                using var reader = new System.IO.StreamReader(response.ResponseStream);
                var content = await reader.ReadToEndAsync();
                var responseBytes = Encoding.UTF8.GetBytes(content);
                await ws.SendAsync(new ArraySegment<byte>(responseBytes),
                    WebSocketMessageType.Text, true, CancellationToken.None);
            }
            catch (Exception ex)
            {
                var errBytes = Encoding.UTF8.GetBytes($"{{\"error\":\"{ex.Message}\"}}");
                await ws.SendAsync(new ArraySegment<byte>(errBytes),
                    WebSocketMessageType.Text, true, CancellationToken.None);
            }
        }
        else if (command?.Action == "write")
        {
            var s3 = context.RequestServices.GetRequiredService<IAmazonS3>();
            // User-controlled write to arbitrary bucket/key
            await s3.PutObjectAsync(new PutObjectRequest
            {
                BucketName = command.Bucket,
                Key = command.Key,
                ContentBody = command.Data
            });
            var ack = Encoding.UTF8.GetBytes("{\"status\":\"written\"}");
            await ws.SendAsync(new ArraySegment<byte>(ack),
                WebSocketMessageType.Text, true, CancellationToken.None);
        }
    }
});

app.Run("http://0.0.0.0:5000");

public class SyncCommand
{
    public string Action { get; set; }
    public string Bucket { get; set; }
    public string Key { get; set; }
    public string Data { get; set; }
}
